fn insert_before_each(arr: &Vec<i32>, elem: i32) -> Vec<i32> {
    // Pre-allocate a vector with twice the capacity of the input array
    let mut result = Vec::with_capacity(arr.len() * 2);

    // For each element in the input, first push `elem`, then the element itself
    for &x in arr.iter() {
        result.push(elem);
        result.push(x);
    }

    result
}

